namespace docking.widgets.filechooser;





using docking.widgets.table;

class DirectoryTableModel : AbstractSortedTableModel<File> {
	private static readonly long serialVersionUID = 1L;

	static int FILE_COL = 0;
	static int SIZE_COL = 1;
	static int TIME_COL = 2;

	private GhidraFileChooser chooser;
	private List<File> files = new();

	DirectoryTableModel(GhidraFileChooser chooser) : base(FILE_COL)
    {
		this.chooser = chooser;
	}

	void insert(File file) {
		int len = files.size();
		files.add(file);
		fireTableRowsInserted(len, len);
	}

	void setFiles(List<File> fileList) {
		files.clear();
		files.addAll(fileList);
		fireTableDataChanged();
	}

	File getFile(int row) {
		if (row >= 0 && row < files.size()) {
			return files.get(row);
		}
		return null;
	}

	void setFile(int row, File file) {
		if (row >= 0 && row < files.size()) {
			files.set(row, file);
			fireTableRowsUpdated(row, row);
		}
	}

	/* @Override */
	public string getName() {
		return "Directory";
	}

	/* @Override */
	public int getRowCount() {
		return files.size();
