			case TIME_COL:
				return typeof(Date);
		}
		return typeof(string);
	}

	/* @Override */
	public string getColumnName(int column) {
		switch (column) {
			case FILE_COL:
				return "Filename";
			case SIZE_COL:
				return "Size";
			case TIME_COL:
				return "Modified";
		}
		return "<<unknown>>";
	}

	/* @Override */
	public object getColumnValueForRow(File file, int columnIndex) {
		switch (columnIndex) {
			case FILE_COL:
				return file;
			case SIZE_COL:
				if (!chooser.getModel().isDirectory(file)) {
					return file.length();
				}
				break;
			case TIME_COL:
				return new Date(file.lastModified());
		}
