		}

		if (aValue == null) {
			return;
		}

		switch (column) {
			case FILE_COL:
				files.set(row, (File) aValue);
				update();
				break;
		}
	}

	void update() {
		fireTableDataChanged();
	}

	/* @Override */
	protected Comparator<File> createSortComparator(int columnIndex) {
		switch (columnIndex) {
